import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { JobService } from "../application/job-service.js";
import { NotFoundError } from "../../../packages/shared/src/errors.js";

const CreateBody = z.object({ inputUri: z.string().url(), renderer: z.enum(["pdf", "png", "svg"]) });

export async function registerJobRoutes(app: FastifyInstance, service: JobService): Promise<void> {
  app.post("/v1/jobs", async (request, reply) => {
    const tenantId = request.user.tenantId;
    const body = CreateBody.parse(request.body);
    const result = await service.create(tenantId, body, request.headers["idempotency-key"]);
    return reply.code(result.statusCode).send(result.body);
  });

  app.get<{ Params: { id: string } }>("/v1/jobs/:id", async (request, reply) => {
    const job = await app.jobs.find(request.user.tenantId, request.params.id);
    if (!job) throw new NotFoundError("job");
    return reply.send(job);
  });

  app.post<{ Params: { id: string } }>("/v1/jobs/:id/cancel", async (request, reply) => {
    const job = await service.cancel(request.user.tenantId, request.params.id, "user_request");
    return reply.send(job);
  });
}
