import type { Pool } from "pg";
import type { JobEvent } from "./job-events.js";

export interface StoredEvent {
  tenantId: string;
  jobId: string;
  sequence: number;
  payload: JobEvent;
}

export class EventStore {
  constructor(private readonly pool: Pool) {}

  async listAfter(tenantId: string, jobId: string, sequence: number): Promise<StoredEvent[]> {
    const result = await this.pool.query<StoredEvent>(
      `SELECT tenant_id AS "tenantId", job_id AS "jobId", sequence, payload
       FROM job_events WHERE tenant_id = $1 AND job_id = $2 AND sequence > $3
       ORDER BY sequence ASC`,
      [tenantId, jobId, sequence],
    );
    return result.rows;
  }

  async append(client: import("pg").PoolClient, event: JobEvent): Promise<void> {
    await client.query(
      `INSERT INTO job_events (event_id, tenant_id, job_id, sequence, type, payload, occurred_at)
       VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7)
       ON CONFLICT (tenant_id, job_id, sequence) DO NOTHING`,
      [event.eventId, event.tenantId, event.jobId, event.sequence, event.type,
       JSON.stringify(event), event.occurredAt],
    );
  }
}
